package scholarchain.storage

import java.nio.charset.StandardCharsets
import java.nio.file.{Files, Path}

import scala.jdk.CollectionConverters.*

import scholarchain.core.*

/** Independent checks of the NEWEST real local loader output (the highest `modules/storage/target/
  * loads/L<n>` directory). Skipped with an explicit message when none is present (it is produced by
  * `LocalLoad`, not by `sbt check`). The core behaviors are also covered by the self-contained
  * fixtures elsewhere. The output is not regenerated by this suite, so it checks whatever the
  * newest loader run produced (a stale output is a known limit, see the test report).
  */
class LocalLoadOutputSuite extends munit.FunSuite:

  private def l1: Path =
    val loads = StorageFx.repoRoot.map(_.resolve("modules/storage/target/loads"))
    assume(
      loads.exists(Files.isDirectory(_)),
      "modules/storage/target/loads is not present: run LocalLoad to produce a loader output",
    )
    val dirs = loadDirs(loads.get)
    assume(dirs.nonEmpty, "modules/storage/target/loads holds no L<n> output: run LocalLoad")
    dirs.last

  /** Output directories `L<n>`, ordered by n. */
  private def loadDirs(loads: Path): List[Path] =
    val s = Files.list(loads)
    try
      s.iterator.asScala.toList
        .filter(p => Files.isDirectory(p) && p.getFileName.toString.matches("L[0-9]+"))
        .sortBy(_.getFileName.toString.drop(1).toInt)
    finally s.close()

  private def csv(p: Path): Vector[Vector[String]] =
    CsvFormat
      .parse(new String(Files.readAllBytes(p), StandardCharsets.UTF_8))
      .fold(e => fail(s"$p: $e"), identity)

  private def files(dir: Path): List[Path] =
    val s = Files.list(dir)
    try s.iterator.asScala.toList.sortBy(_.toString)
    finally s.close()

  test(
    "newest output: every edge endpoint is a vertex ID, IDs are unique, and the manifest row counts match"
  ) {
    val root     = l1
    val vertices = files(root.resolve("neptune/vertices")).map(f =>
      f.getFileName.toString.stripSuffix(".csv") -> csv(f)
    )
    val edges = files(root.resolve("neptune/edges")).map(f =>
      f.getFileName.toString.stripSuffix(".csv") -> csv(f)
    )
    val ids = vertices.flatMap(_._2.tail.map(_(0)))
    assertEquals(ids.distinct.size, ids.size, "duplicate vertex IDs")
    val idSet   = ids.toSet
    val edgeIds = edges.flatMap(_._2.tail.map(_(0)))
    assertEquals(edgeIds.distinct.size, edgeIds.size, "duplicate edge IDs")
    var dangling = 0
    edges.foreach { (_, rows) =>
      rows.tail.foreach(r => if !idSet(r(1)) || !idSet(r(2)) then dangling += 1)
    }
    assertEquals(dangling, 0)
    val manifest = ujson.read(Files.readAllBytes(root.resolve("load-manifest.json")))
    val nep      = manifest("neptune")
    vertices.foreach((label, rows) =>
      assertEquals(rows.size - 1L, nep("vertexRows")(label).num.toLong, label)
    )
    edges.foreach((label, rows) =>
      assertEquals(rows.size - 1L, nep("edgeRows")(label).num.toLong, label)
    )
  }

  test(
    "newest output: COAUTHORED_WITH rows carry the evidence pointer (evidenceKey = edge ID, evidencePartition = window)"
  ) {
    val rows                  = csv(l1.resolve("neptune/edges/COAUTHORED_WITH.csv"))
    val h                     = rows.head
    def ix(n: String)         = h.indexWhere(_.startsWith(n + ":"))
    val (key, part, win, tbl) =
      (ix("evidenceKey"), ix("evidencePartition"), ix("window"), ix("evidenceTable"))
    assert(Seq(key, part, win, tbl).forall(_ >= 0), h.toString)
    assert(rows.tail.nonEmpty)
    rows.tail.foreach { r =>
      assertEquals(r(key), r(0))
      assertEquals(r(part), r(win))
      assertEquals(r(tbl), "coauthor-edge-works")
      assert(r(0).startsWith("edge:coauthor:"))
      assert(r(1) < r(2), "undirected edges are stored once, smaller ID first")
    }
  }

  test(
    "newest output: Researcher IDs have the core researcher ID shape and checksums.sha256 matches the files"
  ) {
    val root = l1
    csv(root.resolve("neptune/vertices/Researcher.csv")).tail.foreach(r =>
      assert(Ids.checkResearcherId(r(0)).isRight, r(0))
    )
    val lines =
      Files.readAllLines(root.resolve("checksums.sha256")).asScala.toList.filter(_.nonEmpty)
    assert(lines.nonEmpty)
    lines.foreach { l =>
      val Array(hash, name) = l.split("  ", 2)
      val actual            = Hashing.sha256Hex(Files.readAllBytes(root.resolve(name)))
      assertEquals(actual, hash, name)
    }
  }

  // ---- M6 / M8 on the newest output ---------------------------------------------------------------

  private def manifestOf(root: Path) =
    ujson.read(Files.readAllBytes(root.resolve("load-manifest.json")))

  test(
    "newest output: every Neptune file ends with the lineage columns and every row carries them"
  ) {
    val root       = l1
    val m          = manifestOf(root)
    val loadRun    = m("loadRunId").str
    val sparkRun   = m("input")("sparkRunId").str
    val docs       = m("provenanceDocuments").obj.keySet
    val tableLevel = m("neptuneLineage")("tableLevelDigests").obj.values.map(_.str).toSet
    val all        = files(root.resolve("neptune/vertices")) ++ files(root.resolve("neptune/edges"))
    assert(all.nonEmpty)
    all.foreach { f =>
      val rows = csv(f)
      assertEquals(
        rows.head.takeRight(3),
        Vector("loadRunId:String", "sparkRunId:String", "provenanceDigest:String"),
        f.getFileName.toString,
      )
      rows.tail.foreach { r =>
        assertEquals(r(r.size - 3), loadRun, f.getFileName.toString)
        assertEquals(r(r.size - 2), sparkRun, f.getFileName.toString)
        assert(
          docs.contains(r.last) || tableLevel.contains(r.last),
          s"${f.getFileName}: digest ${r.last} is not in provenanceDocuments or the table-level digests",
        )
      }
    }
  }

  test(
    "newest output: the row digest of a provenance-carrying edge table is SHA-256 of a documented provenance"
  ) {
    val root = l1
    val docs = manifestOf(root)("provenanceDocuments").obj
    val rows = csv(root.resolve("neptune/edges/COAUTHORED_WITH.csv"))
    assert(rows.tail.nonEmpty)
    val digests = rows.tail.map(_.last).distinct
    assert(digests.forall(docs.contains), digests.take(3).toString)
    digests.take(5).foreach { d =>
      val text = ujson.write(docs(d)) // the manifest stores the parsed JSON of the provenance
      assert(text.nonEmpty)
    }
  }

  test("newest output: the loader published the load manifest into the fake object store") {
    val root = l1
    val dir  = root.resolve("object-store/data")
    assert(Files.isDirectory(dir), "no object-store/data: the manifest was not published")
    val s         = Files.walk(dir)
    val published =
      try s.iterator.asScala.filter(Files.isRegularFile(_)).map(_.getFileName.toString).toList
      finally s.close()
    assert(published.contains("manifest.json"), published.toString)
    assert(published.contains("load-manifest.json"), published.toString)
  }

  test(
    "newest output: the analytics item files reload twice through AnalyticsRepository, the second pass all Unchanged"
  ) {
    val root     = l1
    val itemsDir = root.resolve("dynamodb/items")
    assume(Files.isDirectory(itemsDir), "no dynamodb/items in the newest output")
    val cfg    = StorageConfigLoader.load().fold(e => fail(e.toString), _.config)
    val kv     = InMemoryKeyValueStore(AnalyticsRepository.schemas(cfg.tables))
    val repo   = AnalyticsRepository.fromConfig(kv, cfg.tables)
    val parsed = files(itemsDir).filter(_.toString.endsWith(".jsonl")).flatMap { f =>
      val table = f.getFileName.toString.stripSuffix(".jsonl")
      Files.readAllLines(f).asScala.toList.filter(_.nonEmpty).map { line =>
        val j     = ujson.read(line)
        val attrs = ujson.write(j("attributes"))
        // independent check: the stored hash is the SHA-256 of the compact attributes JSON
        assertEquals(j("payloadHash").str, Cells.sha256(attrs), table)
        AnalyticsItems.AnalyticsItem(
          j("table").str,
          j("pk").str,
          j.obj.get("sk").map(_.str),
          attrs,
          j("payloadHash").str,
        )
      }
    }
    assert(parsed.nonEmpty)
    assertEquals(
      parsed.map(_.table).distinct.sorted,
      StorageConfigKeys.AnalyticsLogicalNames.sorted,
    )
    val r1 = repo.putAll(parsed).fold(e => fail(e.toString), identity)
    assertEquals(r1.conflicts, 0L)
    assertEquals(r1.written, parsed.size.toLong)
    val r2 = repo.putAll(parsed).fold(e => fail(e.toString), identity)
    assertEquals((r2.written, r2.unchanged, r2.conflicts), (0L, parsed.size.toLong, 0L))
  }
